	"QgghhBBCCCFknvH/ATiphDwcPXRvAAAAAElFTkSuQmCC\" alt=\"Sonix\">\n</header>\n\n<section class=\"shell\" id=\"pai"
	"r-panel\" hidden>\n  <form class=\"card\" id=\"pair-form\" action=\"pair\" method=\"post\">\n    <h2>{{Collega "
	"il browser}}</h2>\n    <p>{{Inserisci il codice mostrato nella pagina Trasferimento del V1.}}</p>\n   "
	" <input type=\"text\" id=\"pair-code\" aria-label=\"{{Codice di abbinamento}}\"\n           autocomplete=\"o"
	"ff\" autocapitalize=\"characters\" spellcheck=\"false\" maxlength=\"8\" required>\n    <div class=\"actions\">"
	"<button class=\"btn accent\" id=\"pair-connect\">{{Connetti}}</button></div>\n    <p id=\"pair-status\" rol"
	"e=\"status\"></p>\n  </form>\n</section>\n\n<div class=\"shell\" id=\"files-shell\" hidden>\n\n  <div class=\"hea"
	"d\">\n    <div class=\"where\">\n      <h1 id=\"title\">{{Scheda microSD}}</h1>\n      <div class=\"count\" id"
	"=\"count\"></div>\n    </div>\n    <div class=\"tools\">\n      <button class=\"btn accent\" id=\"pick\" aria-l"
	"abel=\"{{Carica file}}\">\n        <svg class=\"svgicon\"><use href=\"#upload\"/></svg><span class=\"label\">"
	"{{Carica file}}</span>\n      </button>\n      <button class=\"btn\" id=\"pick-folder\" aria-label=\"{{Cari"
	"ca cartella}}\">\n        <svg class=\"svgicon\"><use href=\"#folder\"/></svg><span class=\"label\">{{Carica"
	" cartella}}</span>\n      </button>\n      <button class=\"btn\" id=\"mkdir\" aria-label=\"{{Nuova cartella"
	"}}\">\n        <svg class=\"svgicon\"><use href=\"#folder-new\"/></svg><span class=\"label\">{{Nuova cartell"
	"a}}</span>\n      </button>\n      <button class=\"btn btn-icon\" id=\"hidden\" title=\"{{Mostra file nasco"
	"sti}}\" aria-label=\"{{Mostra file nascosti}}\">\n        <svg class=\"svgicon big\"><use href=\"#eye-off\"/"
	"></svg>\n      </button>\n      <button class=\"btn btn-icon\" id=\"reload\" title=\"{{Aggiorna}}\" aria-lab"
	"el=\"{{Aggiorna}}\">\n        <svg class=\"svgicon big\"><use href=\"#refresh\"/></svg>\n      </button>\n   "
	" </div>\n  </div>\n\n  <nav class=\"crumbs\" id=\"crumbs\"></nav>\n\n  <input class=\"hidden-input\" type=\"file"
	"\" id=\"files\" multiple>\n  <!-- The folder picker. `webkitdirectory` is the only way a browser will ha"
	"nd\n       over a whole tree. Every file then\n       carries a webkitRelativePath, which is how the s"
	"tructure survives the\n       trip. -->\n  <input class=\"hidden-input\" type=\"file\" id=\"folders\" webkit"
	"directory directory multiple>\n\n  <div class=\"uploads\" id=\"uploads\"></div>\n\n  <div class=\"colhead\">\n "
	"   <span></span><span>{{Nome}}</span><span class=\"size\">{{Dimensione}}</span><span>{{Modificato}}</s"
	"pan><span></span>\n  </div>\n  <div class=\"list\" id=\"list\"><div class=\"loading\">{{Caricamento...}}</di"
	"v></div>\n</div>\n\n<!-- prompt: create folder, rename, move -->\n<div class=\"veil\" id=\"prompt-veil\" hid"
	"den>\n  <div class=\"card\">\n    <h2 id=\"prompt-title\"></h2>\n    <p id=\"prompt-note\" hidden></p>\n    <i"
	"nput type=\"text\" id=\"prompt-input\" autocomplete=\"off\" spellcheck=\"false\">\n    <div class=\"actions\">\n"
	"      <button class=\"btn\" data-close=\"prompt\">{{Annulla}}</button>\n      <button class=\"btn accent\" "
	"id=\"prompt-ok\">{{OK}}</button>\n    </div>\n  </div>\n</div>\n\n<!-- the folder picker: where a move goes"
	" -->\n<div class=\"veil\" id=\"picker-veil\" hidden>\n  <div class=\"card wide\">\n    <h2>{{Sposta}}</h2>\n  "
	"  <p id=\"picker-note\"></p>\n    <div class=\"pickhere\" id=\"picker-crumbs\"></div>\n    <div class=\"picke"
	"r\" id=\"picker-list\"></div>\n    <div class=\"actions\">\n      <button class=\"btn\" data-close=\"picker\">{"
	"{Annulla}}</button>\n      <button class=\"btn accent\" id=\"picker-ok\">{{Sposta qui}}</button>\n    </di"
	"v>\n  </div>\n</div>\n\n<!-- confirm: delete -->\n<div class=\"veil\" id=\"confirm-veil\" hidden>\n  <div clas"
	"s=\"card\">\n    <h2 id=\"confirm-title\"></h2>\n    <p id=\"confirm-note\"></p>\n    <div class=\"actions\">\n "
	"     <button class=\"btn\" data-close=\"confirm\">{{Annulla}}</button>\n      <button class=\"btn danger\" "
	"id=\"confirm-ok\">{{Elimina}}</button>\n    </div>\n  </div>\n</div>\n\n<div class=\"toasts\" id=\"toasts\"></d"
	"iv>\n\n<script>\n\"use strict\";\n\nvar CARD = \"/\";\n\n/* Warn about unfamiliar types without rejecting cover"
	" art, CUE files, or\n   other files that may be part of an album folder. */\nvar AUDIO     = [\"ISO\",\"D"
	"FF\",\"DSF\",\"DTS\",\"APE\",\"FLAC\",\"AIF\",\"AIFF\",\"WAV\",\"M4A\",\"AAC\",\n                 \"MP2\",\"MP3\",\"OGG\",\"OGA"
	"\",\"WMA\",\"OPUS\",\"DSD\",\"WV\",\"MPC\",\"TAK\",\"TTA\"];\nvar AUDIOBOOK = [\"M4B\",\"AA\",\"AAX\"];\nvar PLAYLIST  = [\""
	"M3U\",\"M3U8\",\"CUE\"];\nvar IMAGE     = [\"BMP\",\"PNG\",\"JPG\",\"JPEG\",\"GIF\",\"WEBP\"];\nvar TEXT      = [\"LRC\","
	"\"TXT\",\"T\",\"INI\",\"NFO\"];\nvar FIRMWARE  = [\"UPT\"];\n/* Le rom del Game Boy e i loro salvataggi, i libri"
	", e i caratteri che il\n   lettore di EPUB prende da .local/fonts: roba che il player usa davvero, e\n"
	"   che finiva sotto l'avviso \"non e' un formato che il player legge\". */\nvar GAME      = [\"GB\",\"GBC\""
	",\"SAV\"];\nvar EBOOK     = [\"EPUB\"];\nvar FONT      = [\"TTF\",\"OTF\"];\n\nvar path = CARD;\nvar entries = []"
	";\nvar openMenu = null;\n\n// Whether the listing includes names beginning with a dot. Off by default: "
	"on a\n// card that has been near a Mac, the interesting files are outnumbered by\n// .Spotlight-V100 a"
	"nd a ._ twin for every track.\nvar showHidden = false;\n\nvar listSerial = 0;\n\nvar $ = function (id) { "
	"return document.getElementById(id); };\n\n/* --- small helpers ---------------------------------------"
	"---------------- */\n\nfunction ext(name) {\n  var dot = name.lastIndexOf(\".\");\n  return dot < 0 \? \"\" :"
	" name.slice(dot + 1).toUpperCase();\n}\n\nfunction glyphFor(entry) {\n  if (entry.dir) { return \"folder\""
	"; }\n  var e = ext(entry.name);\n  if (AUDIO.indexOf(e) >= 0)     { return \"music\"; }\n  if (AUDIOBOOK."
	"indexOf(e) >= 0) { return \"audiobook\"; }\n  if (PLAYLIST.indexOf(e) >= 0)  { return \"file-playlist\"; "
	"}\n  if (IMAGE.indexOf(e) >= 0)     { return \"image\"; }\n  if (TEXT.indexOf(e) >= 0)      { return \"fi"
	"le-text\"; }\n  if (FIRMWARE.indexOf(e) >= 0)  { return \"update-file\"; }\n  if (GAME.indexOf(e) >= 0)  "
	"    { return \"gamepad\"; }\n  if (EBOOK.indexOf(e) >= 0)     { return \"book\"; }\n  return \"file\";\n}\n\nfu"
	"nction isKnown(name) {\n  var e = ext(name);\n  return AUDIO.concat(AUDIOBOOK, PLAYLIST, IMAGE, TEXT, "
	"FIRMWARE, GAME, EBOOK, FONT).indexOf(e) >= 0;\n}\n\n/* The player's own way of putting a size on screen"
	". */\nfunction humanSize(bytes) {\n  if (bytes >= 1073741824) { return (bytes / 1073741824).toFixed(2)"
	" + \" GB\"; }\n  if (bytes >= 1048576)    { return (bytes / 1048576).toFixed(1) + \" MB\"; }\n  if (bytes "
	">= 1024)       { return (bytes / 1024).toFixed(0) + \" KB\"; }\n  return bytes + \" B\";\n}\n\nfunction huma"
	"nDate(secs) {\n  if (!secs) { return \"\"; }\n  var d = new Date(secs * 1000);\n  var two = function (n) "
	"{ return (n < 10 \? \"0\" : \"\") + n; };\n  return two(d.getDate()) + \"/\" + two(d.getMonth() + 1) + \"/\" +"
	" d.getFullYear() +\n         \" \" + two(d.getHours()) + \":\" + two(d.getMinutes());\n}\n\nfunction isCard("
	"p) { return p === CARD; }\nfunction normalise(p) { return p.replace(/\\/+/g, \"/\"); }\n\nfunction rootLab"
	"el() { return \"{{js|Scheda microSD}}\"; }\n\n/* The two markers, and why there are two.\n\n   A doubled-b"
	"race marker is replaced by the player when it writes this page out\n   (src/system/net/wifitransfer.c"
	"). A plain one is escaped as HTML,\n   which is right for the markup and the HTML fragments built bel"
	"ow in\n   JavaScript. One prefixed\n   with \"js|\" is escaped for JavaScript instead, and is for text t"
	"hat reaches\n   the page through textContent or a DOM property, where an escaped entity\n   would be s"
	"hown literally.\n\n   Getting that the wrong way round is not cosmetic. The French for \"is not\"\n   car"
	"ries an apostrophe, and an apostrophe closes a string: the page would not\n   parse at all.\n\n   fill("
	") puts {1}, {2}... back into a translated string. Numbered rather than\n   taken in order, because a "
	"translation is allowed to want the pieces\n   somewhere else in the sentence than the Italian puts th"
	"em, and a sentence\n   that has been reordered would otherwise take the wrong values. */\nfunction fil"
	"l(s) {\n  var args = arguments;\n  return s.replace(/\\{(\\d)\\}/g, function (whole, n) {\n    var v = arg"
	"s[Number(n)];\n    return v === undefined \? whole : v;\n  });\n}\n\nfunction icon(name, cls) {\n  return '"
	"<svg class=\"svgicon' + (cls \? \" \" + cls : \"\") + '\"><use href=\"#' + name + '\"/></svg>';\n}\n\n/* --- toa"
	"sts -------------------------------------------------------------- */\n\nfunction toast(message, kind)"
	" {\n  var el = document.createElement(\"div\");\n  el.className = \"toast \" + (kind || \"error\");\n  el.inn"
	"erHTML = icon(kind === \"ok\" \? \"check\" : \"alert\") + \"<span></span>\";\n  el.lastChild.textContent = mes"
	"sage;\n  $(\"toasts\").appendChild(el);\n  setTimeout(function () { el.remove(); }, kind === \"ok\" \? 2200"
	" : 5000);\n}\n\n/* --- the dialogs -------------------------------------------------------- */\n\nfunctio"
	"n askText(title, note, value, okLabel, done) {\n  $(\"prompt-title\").textContent = title;\n  var noteEl"
	" = $(\"prompt-note\");\n  if (note) { noteEl.textContent = note; noteEl.hidden = false; } else { noteEl"
	".hidden = true; }\n  var input = $(\"prompt-input\");\n  input.value = value || \"\";\n  $(\"prompt-ok\").tex"
	"tContent = okLabel || \"{{js|OK}}\";\n  $(\"prompt-veil\").hidden = false;\n  input.focus();\n  input.selec"
	"t();\n\n  $(\"prompt-ok\").onclick = function () {\n    var v = input.value.trim();\n    $(\"prompt-veil\")."
	"hidden = true;\n    if (v) { done(v); }\n  };\n}\n\nfunction askConfirm(title, note, okLabel, done) {\n  $"
	"(\"confirm-title\").textContent = title;\n  $(\"confirm-note\").textContent = note || \"\";\n  $(\"confirm-ok"
	"\").textContent = okLabel || \"{{js|Elimina}}\";\n  $(\"confirm-veil\").hidden = false;\n  $(\"confirm-ok\")."
	"onclick = function () {\n    $(\"confirm-veil\").hidden = true;\n    done();\n  };\n}\n\ndocument.addEventLi"
	"stener(\"click\", function (e) {\n  var close = e.target.closest \? e.target.closest(\"[data-close]\") : n"
	"ull;\n  if (close) { $(close.dataset.close + \"-veil\").hidden = true; }\n});\n\n/* ----------------------"
	"-----------------------------------------------------\n   The folder picker.\n\n   `forbidden` is the f"
	"older being moved: you cannot move something into itself,\n   and since the only way down is through "
	"this list, refusing to show it also\n   refuses every path underneath it.\n   ------------------------"
	"--------------------------------------------------- */\nfunction askFolder(note, start, forbidden, do"
	"ne) {\n  var here = start;\n\n  var drawHere = function () {\n    var el = $(\"picker-crumbs\");\n    el.in"
	"nerHTML = \"\";\n\n    var add = function (label, target) {\n      if (el.childNodes.length) {\n        va"
	"r sep = document.createElement(\"span\");\n        sep.className = \"sep\";\n        sep.innerHTML = icon("
	"\"chevron-right\");\n        el.appendChild(sep);\n      }\n      if (target === null) {\n        var span"
	" = document.createElement(\"span\");\n        span.className = \"here\";\n        span.textContent = label"
	";\n        el.appendChild(span);\n      } else {\n        var a = document.createElement(\"a\");\n        "
	"a.textContent = label;\n        a.onclick = function () { go(target); };\n        el.appendChild(a);\n "
	"     }\n    };\n\n    var rest = here.slice(CARD.length).replace(/\\/$/, \"\");\n    var parts = rest \? res"
	"t.split(\"/\") : [];\n\n    add(rootLabel(), parts.length \? CARD : null);\n    parts.forEach(function (pa"
	"rt, i) {\n      var target = CARD + parts.slice(0, i + 1).join(\"/\") + \"/\";\n      add(part, i === part"
	"s.length - 1 \? null : target);\n    });\n  };\n\n  var go = function (target) {\n    target = normalise(t"
	"arget);\n    here = target;\n    drawHere();\n\n    var box = $(\"picker-list\");\n    box.innerHTML = '<di"
	"v class=\"none\">' + icon(\"loader\", \"big spin\") + \"</div>\";\n\n    listing(target)\n      .then(function "
	"(data) {\n        if (here !== target || $(\"picker-veil\").hidden) { return; }\n        var dirs = (dat"
	"a || []).filter(function (f) {\n          var isDir = f.size === undefined || f.size === null;\n      "
	"    return isDir && f.path !== forbidden;\n        }).sort(function (a, b) {\n          return a.name."
	"localeCompare(b.name, undefined, { numeric: true, sensitivity: \"base\" });\n        });\n\n        box.i"
	"nnerHTML = \"\";\n        if (!dirs.length) {\n          box.innerHTML = '<div class=\"none\">{{Nessuna so"
	"ttocartella. Premi \"Sposta qui\".}}</div>';\n          return;\n        }\n\n        dirs.forEach(functio"
	"n (f) {\n          var b = document.createElement(\"button\");\n          b.innerHTML = icon(\"folder\", \""
	"big\") + \"<span></span>\";\n          b.lastChild.textContent = f.name;\n          b.onclick = function "
	"() { go(f.path); };\n          box.appendChild(b);\n        });\n      })\n      .catch(function (err) {"
	"\n        if (here !== target || $(\"picker-veil\").hidden) { return; }\n        box.innerHTML = '<div c"
	"lass=\"none\">{{Impossibile leggere questa cartella.}}</div>';\n        toast(fill(\"{{js|Lettura di {1}"
	" non riuscita ({2})}}\", here, err.message));\n      });\n  };\n\n  $(\"picker-note\").textContent = note |"
	"| \"\";\n  $(\"picker-veil\").hidden = false;\n  go(start);\n\n  $(\"picker-ok\").onclick = function () {\n    "
	"$(\"picker-veil\").hidden = true;\n    done(here);\n  };\n}\n\n$(\"prompt-input\").addEventListener(\"keydown\""
	", function (e) {\n  if (e.key === \"Enter\") { $(\"prompt-ok\").click(); }\n  if (e.key === \"Escape\") { $("
	"\"prompt-veil\").hidden = true; }\n});\n\ndocument.addEventListener(\"keydown\", function (e) {\n  if (e.key"
	" !== \"Escape\") { return; }\n  closeMenu();\n  $(\"confirm-veil\").hidden = true;\n  $(\"picker-veil\").hidd"
	"en = true;\n});\n\n/* --- session and requests ---------------------------------------------- */\n\nfunct"
	"ion showPair(note) {\n  ++listSerial;\n  queue.length = 0;\n  madeDirs = Object.create(null);\n  closeMe"
	"nu();\n  [\"prompt\", \"confirm\", \"picker\"].forEach(function (id) { $(id + \"-veil\").hidden = true; });\n "
	" $(\"files-shell\").hidden = true;\n  $(\"pair-panel\").hidden = false;\n  $(\"pair-status\").textContent = "
	"note || \"\";\n}\n\nfunction connectionLost() {\n  showPair(\"{{js|Impossibile connettersi. Lascia aperta l"
	"a pagina Trasferimento sul V1.}}\");\n}\n\nfunction statusMessage(status) {\n  if (status === 409) { retu"
	"rn \"{{js|Esiste gi\303\240 un file o una cartella con questo nome.}}\"; }\n  if (status === 413) { return \"{"
	"{js|File troppo grande (limite: 4 GiB meno un byte).}}\"; }\n  if (status === 507) { return \"{{js|Spaz"
	"io insufficiente sulla microSD.}}\"; }\n  return \"HTTP \" + status;\n}\n\nfunction checkResponse(res) {\n  "
	"if (res.ok) { return res; }\n  if (res.status === 401) { showPair(); }\n  var err = new Error(statusMe"
	"ssage(res.status));\n  err.status = res.status;\n  throw err;\n}\n\nfunction pair(code) {\n  if (!/^[2-9A-"
	"HJ-NP-Z]{8}$/.test(code)) {\n    showPair(\"{{js|Codice non valido o scaduto.}}\");\n    return;\n  }\n  $"
	"(\"pair-connect\").disabled = true;\n  $(\"pair-status\").textContent = \"{{js|Connessione...}}\";\n  fetch("
	"\"pair\", { method: \"POST\", headers: { \"X-Sonix-Pair\": code } })\n    .then(function (res) {\n      if ("
	"res.status === 401) { showPair(\"{{js|Codice non valido o scaduto.}}\"); }\n      else if (!res.ok) { t"
	"hrow new Error(statusMessage(res.status)); }\n      else {\n        $(\"pair-code\").value = \"\";\n       "
	" load(CARD);\n      }\n    })\n    .catch(connectionLost)\n    .then(function () { $(\"pair-connect\").dis"
	"abled = false; });\n}\n\n$(\"pair-form\").onsubmit = function (e) {\n  e.preventDefault();\n  if (!$(\"pair-"
	"connect\").disabled) { pair($(\"pair-code\").value.trim().toUpperCase()); }\n};\n\nfunction endpoint(route"
	", fields) {\n  return route + \"\?\" + Object.keys(fields).map(function (k) {\n    return k + \"=\" + encod"
	"eURIComponent(fields[k]);\n  }).join(\"&\");\n}\n\nfunction post(route, fields) {\n  return fetch(endpoint("
	"route, fields), {\n    method: \"POST\",\n    headers: { \"X-Sonix-Transfer\": \"1\" }\n  }).then(checkRespon"
	"se);\n}\n\nfunction listing(target) {\n  return fetch(endpoint(\"list\", { path: target, hidden: showHidde"
	"n \? 1 : 0 }), { cache: \"no-store\" })\n    .then(checkResponse)\n    .then(function (res) { return res."
	"json(); });\n}\n\nfunction load(target) {\n  path = normalise(target);\n  var serial = ++listSerial;\n  cl"
	"oseMenu();\n  $(\"list\").innerHTML = '<div class=\"loading\">' + icon(\"loader\", \"big spin\") + \"</div>\";\n"
	"\n  listing(path)\n    .then(function (data) {\n      if (serial !== listSerial) { return; }\n      $(\"p"
	"air-panel\").hidden = true;\n      $(\"files-shell\").hidden = false;\n      entries = (data || []).map(f"
	"unction (f) {\n        return {\n          name: f.name,\n          path: f.path,\n          dir: f.size"
	" === undefined || f.size === null,\n          size: f.size,\n          ctime: parseInt(f.ctime, 10) ||"
	" 0\n        };\n      });\n\n      // Folders first, then by name: a music card is browsed, not audited,"
	" and\n      // newest-first put the same album somewhere different every time.\n      entries.sort(fun"
	"ction (a, b) {\n        if (a.dir !== b.dir) { return a.dir \? -1 : 1; }\n        return a.name.localeC"
	"ompare(b.name, undefined, { numeric: true, sensitivity: \"base\" });\n      });\n\n      draw();\n    })\n "
	"   .catch(function (err) {\n      if (serial !== listSerial) { return; }\n      if ($(\"files-shell\").h"
	"idden) { connectionLost(); return; }\n      entries = [];\n      $(\"list\").innerHTML = '<div class=\"em"
	"pty\">{{Impossibile leggere questa cartella.}}</div>';\n      drawCrumbs();\n      toast(fill(\"{{js|Let"
	"tura di {1} non riuscita ({2})}}\", path, err.message));\n    });\n}\n\n/* --- drawing ------------------"
	"------------------------------------------ */\n\nfunction drawCrumbs() {\n  var el = $(\"crumbs\");\n  el."
	"innerHTML = \"\";\n\n  // At the top there is nothing to walk back through, so there is no trail.\n  if ("
	"isCard(path)) { return; }\n\n  var add = function (label, target) {\n    if (el.childNodes.length) {\n  "
	"    var sep = document.createElement(\"span\");\n      sep.className = \"sep\";\n      sep.innerHTML = ico"
	"n(\"chevron-right\");\n      el.appendChild(sep);\n    }\n    if (target === null) {\n      var here = doc"
	"ument.createElement(\"span\");\n      here.className = \"here\";\n      here.textContent = label;\n      el"
	".appendChild(here);\n    } else {\n      var a = document.createElement(\"a\");\n      a.textContent = la"
	"bel;\n      a.onclick = function () { load(target); };\n      el.appendChild(a);\n    }\n  };\n\n  add(roo"
	"tLabel(), CARD);\n\n  var rest = path.slice(CARD.length).replace(/\\/$/, \"\");\n  var parts = rest \? rest"
	".split(\"/\") : [];\n\n  parts.forEach(function (part, i) {\n    var target = CARD + parts.slice(0, i + 1"
	").join(\"/\") + \"/\";\n    add(part, i === parts.length - 1 \? null : target);\n  });\n}\n\nfunction draw() {"
	"\n  drawCrumbs();\n\n  $(\"title\").textContent = isCard(path)\n    \? rootLabel()\n    : (path.replace(/\\/$"
	"/, \"\").split(\"/\").pop() || rootLabel());\n\n  var dirs = entries.filter(function (e) { return e.dir; }"
	").length;\n  var files = entries.length - dirs;\n  var bits = [];\n  if (dirs)  { bits.push(fill(dirs ="
	"== 1 \? \"{{js|{1} cartella}}\" : \"{{js|{1} cartelle}}\", dirs)); }\n  // \"1 file\" spelled out rather tha"
	"n filled in: Italian does not inflect\n  // \"file\", but German, French and Spanish do, and one key ca"
	"nnot be both\n  // \"1 Datei\" and \"12 Dateien\". When the count is one it IS one, so the\n  // singular "
	"can be a string of its own with nothing to fill.\n  if (files) { bits.push(files === 1 \? \"{{js|1 file"
	"}}\" : fill(\"{{js|{1} file}}\", files)); }\n  $(\"count\").textContent = bits.join(\", \");\n\n\n  var list = "
	"$(\"list\");\n  list.innerHTML = \"\";\n\n  if (!entries.length) {\n    list.innerHTML = '<div class=\"empty\""
	">{{Cartella vuota.}}</div>';\n    return;\n  }\n\n  entries.forEach(function (entry) {\n    var row = doc"
	"ument.createElement(\"div\");\n    row.className = \"row\" + (entry.dir \? \" tappable\" : \"\");\n\n    row.inn"
	"erHTML =\n      '<span class=\"glyph' + (entry.dir \? \" folder\" : \"\") + '\">' + icon(glyphFor(entry), \"b"
	"ig\") + \"</span>\" +\n      '<span class=\"name\"></span>' +\n      '<span class=\"size\">' + (entry.dir \? \""
	"\" : humanSize(entry.size)) + \"</span>\" +\n      '<span class=\"date\">' + humanDate(entry.ctime) + \"</s"
	"pan>\" +\n      '<span class=\"menu\">' +\n        '<button class=\"btn btn-icon\" aria-label=\"{{Azioni}}\">"
	"' + icon(\"dots\", \"big\") + \"</button>\" +\n      \"</span>\";\n\n    row.querySelector(\".name\").textContent"
	" = entry.name;\n\n    if (entry.dir) {\n      row.onclick = function (e) {\n        if (e.target.closest"
	"(\".menu\")) { return; }\n        load(entry.path);\n      };\n    }\n\n    row.querySelector(\".menu button"
	"\").onclick = function (e) {\n      e.stopPropagation();\n      showMenu(row.querySelector(\".menu\"), en"
	"try);\n    };\n\n    list.appendChild(row);\n  });\n}\n\n/* --- the row menu ------------------------------"
	"------------------------- */\n\nfunction closeMenu() {\n  if (openMenu) { openMenu.remove(); openMenu ="
	" null; }\n}\n\ndocument.addEventListener(\"click\", function (e) {\n  if (openMenu && !e.target.closest(\"."
	"menu\")) { closeMenu(); }\n});\n\nfunction showMenu(anchor, entry) {\n  var wasMine = openMenu && openMen"
	"u.parentNode === anchor;\n  closeMenu();\n  if (wasMine) { return; }\n\n  var box = document.createEleme"
	"nt(\"div\");\n  box.className = \"popover\";\n\n  var item = function (glyph, label, cls, action) {\n    var"
	" b = document.createElement(\"button\");\n    if (cls) { b.className = cls; }\n    b.innerHTML = icon(gl"
	"yph) + \"<span></span>\";\n    b.lastChild.textContent = label;\n    b.onclick = function (e) { e.stopPr"
	"opagation(); closeMenu(); action(); };\n    box.appendChild(b);\n  };\n\n  if (entry.dir) {\n    item(\"op"
	"en\", \"{{js|Apri}}\", null, function () { load(entry.path); });\n  } else {\n    item(\"download\", \"{{js|"
	"Scarica}}\", null, function () {\n      window.location = endpoint(\"download\", { path: entry.path });\n"
	"    });\n  }\n\n  item(\"rename\", \"{{js|Rinomina}}\", null, function () { rename(entry); });\n  item(\"move"
	"\", \"{{js|Sposta}}\", null, function () { move(entry); });\n  item(\"delete\", \"{{js|Elimina}}\", \"danger\""
	", function () { remove(entry); });\n\n  anchor.appendChild(box);\n  openMenu = box;\n\n  // Which way it "
	"opens is a question about where the row actually is, not about\n  // where it is in the list: measure"
	", and flip up only when opening down would\n  // run off the bottom AND there is room above. Guessing"
	" from the row index\n  // sent the first row's menu straight over the masthead.\n  var rect = box.getB"
	"oundingClientRect();\n  if (rect.bottom > window.innerHeight - 8 && rect.height + 60 < anchor.getBoun"
	"dingClientRect().top) {\n    box.classList.add(\"up\");\n  }\n}\n\n/* --- the actions ---------------------"
	"----------------------------------- */\n\nfunction rename(entry) {\n  askText(\"{{js|Rinomina}}\", entry."
	"name, entry.name, \"{{js|Rinomina}}\", function (value) {\n    if (value === entry.name) { return; }\n  "
	"  var from = entry.path.replace(/\\/$/, \"\");\n    post(\"move\", { oldPath: from, newPath: path + value "
	"})\n      .then(function () { toast(\"{{js|Rinominato}}\", \"ok\"); })\n      .catch(function (err) { toas"
	"t(fill(\"{{js|Rinomina non riuscita ({1})}}\", err.message)); })\n      .then(function () { load(path);"
	" });\n  });\n}\n\nfunction move(entry) {\n  var from = entry.path.replace(/\\/$/, \"\");\n\n  askFolder(entry."
	"name, path, entry.dir \? entry.path : null, function (dest) {\n    if (dest === path) {\n      return; "
	"// already where it is\n    }\n\n    post(\"move\", { oldPath: from, newPath: dest + entry.name })\n      "
	".then(function () { toast(\"{{js|Spostato}}\", \"ok\"); })\n      .catch(function (err) { toast(fill(\"{{j"
	"s|Spostamento non riuscito ({1})}}\", err.message)); })\n      .then(function () { load(path); });\n  }"
	");\n}\n\nfunction remove(entry) {\n  askConfirm(entry.dir \? \"{{js|Eliminare la cartella\?}}\" : \"{{js|Elim"
	"inare il file\?}}\",\n             entry.dir \? fill(\"{{js|{1} e tutto il suo contenuto.}}\", entry.name)"
	" : entry.name,\n             \"{{js|Elimina}}\", function () {\n    post(\"delete\", { path: entry.path })"
	"\n      .then(function () { toast(\"{{js|Eliminato}}\", \"ok\"); })\n      .catch(function (err) { toast(f"
	"ill(\"{{js|Eliminazione non riuscita ({1})}}\", err.message)); })\n      .then(function () { load(path)"
	"; });\n  });\n}\n\n$(\"mkdir\").onclick = function () {\n  askText(\"{{js|Nuova cartella}}\", null, \"{{js|Nuo"
	"va cartella}}\", \"{{js|Crea}}\", function (name) {\n    post(\"create\", { path: path + name })\n      .th"
	"en(function () { toast(\"{{js|Cartella creata}}\", \"ok\"); })\n      .catch(function (err) { toast(fill("
	"\"{{js|Creazione non riuscita ({1})}}\", err.message)); })\n      .then(function () { load(path); });\n "
	" });\n};\n\n// The eye. Off shows what the card looks like to anything else; on shows the\n// dot-files "
	"too -- .Trashes, ._ twins, whatever a computer left behind.\nfunction updateHiddenButton() {\n  var bu"
	"tton = $(\"hidden\");\n  button.title = showHidden \? \"{{js|Nascondi i file nascosti}}\" : \"{{js|Mostra i"
	" file nascosti}}\";\n\n  button.querySelector(\"use\").setAttribute(\"href\", showHidden \? \"#eye-on\" : \"#ey"
	"e-off\");\n  button.querySelector(\".svgicon\").style.color = showHidden \? \"var(--accent)\" : \"\";\n}\n\n$(\"h"
	"idden\").onclick = function () {\n  showHidden = !showHidden;\n  updateHiddenButton();\n  load(path);\n};"
	"\n\n$(\"reload\").onclick = function () { load(path); };\n\n/* --- uploading -----------------------------"
	"----------------------------- */\n\nvar queue = [];\nvar uploading = false;\n\n/* Folders that have been "
	"created (or found already there) during this run, so\n   a hundred files out of one album cost one `c"
	"reate` and not a hundred. */\nvar madeDirs = Object.create(null);\n\n/* Where a job's file has to land."
	" For a plain pick that is the folder on\n   screen; for a folder pick the relative path carries the s"
	"tructure and the\n   last component of it is the file itself. */\nfunction jobDir(job) {\n  if (!job.re"
	"l) { return job.dir; }\n  var parts = job.rel.split(\"/\").filter(Boolean);\n  parts.pop();\n  return par"
	"ts.length \? job.dir + parts.join(\"/\") + \"/\" : job.dir;\n}\n\n/* Create a dropped tree one parent at a t"
	"ime. A directory already there\n   returns success; a file in its place is a conflict, not a folder t"
	"o skip. */\nfunction ensureDirs(job) {\n  var parts = job.rel \? job.rel.split(\"/\").filter(Boolean) : ["
	"];\n  parts.pop();\n\n  var here = job.dir;\n  var chain = Promise.resolve();\n\n  parts.forEach(function "
	"(part) {\n    here += part + \"/\";\n    var target = here;\n    chain = chain.then(function () {\n      i"
	"f (madeDirs[target]) { return; }\n      return post(\"create\", { path: target }).then(function () { ma"
	"deDirs[target] = true; });\n    });\n  });\n\n  return chain;\n}\n\nfunction enqueue(files, fromFolder, tar"
	"get) {\n  if ($(\"files-shell\").hidden) { return; }\n  var unknown = 0;\n\n  Array.prototype.forEach.call"
	"(files, function (file) {\n    var rel = file.webkitRelativePath || file.sonixRelativePath || \"\";\n   "
	" if (!isKnown(file.name)) {\n      unknown++;\n      // One file at a time is worth naming. A folder o"
	"f two hundred is not:\n      // it would be two hundred notices for one decision.\n      if (!fromFold"
	"er) {\n        toast(fill('{{js|\"{1}\" non \303\250 un formato che il player legge; lo carico comunque.}}', "
	"file.name));\n      }\n    }\n    queue.push({ file: file, dir: target || path, rel: rel });\n  });\n\n  i"
	"f (fromFolder && unknown) {\n    toast(fill(unknown === 1\n               \? \"{{js|{1} file non \303\250 in u"
	"n formato che il player legge; lo carico comunque.}}\"\n               : \"{{js|{1} file non sono in un"
	" formato che il player legge; li carico comunque.}}\", unknown));\n  }\n\n  pump();\n}\n\nfunction pump() {"
	"\n  if (uploading || $(\"files-shell\").hidden) { return; }\n  var job = queue.shift();\n  if (!job) { ma"
	"deDirs = Object.create(null); load(path); return; }\n\n  uploading = true;\n\n  var card = document.crea"
	"teElement(\"div\");\n  card.className = \"upload\";\n  card.innerHTML =\n    '<div class=\"head2\">' +\n      "
	"icon(\"upload\", \"big\") +\n      '<span class=\"name\"></span>' +\n      '<span class=\"pct\">0%</span>' +\n "
	"     '<button class=\"btn btn-icon\" aria-label=\"{{Annulla}}\">' + icon(\"close\", \"big\") + \"</button>\" +"
	"\n    \"</div>\" +\n    '<div class=\"bar\"><span></span></div>';\n  // The relative path, when there is on"
	"e: with a folder on the way up, \"03.mp3\"\n  // on its own does not say which of the four \"03.mp3\" is "
	"being sent.\n  card.querySelector(\".name\").textContent = job.rel || job.file.name;\n  $(\"uploads\").app"
	"endChild(card);\n\n  var xhr = null;\n  var cancelled = false;\n  card.querySelector(\".head2 button\").on"
	"click = function () {\n    cancelled = true;\n    if (xhr) { xhr.abort(); }\n  };\n\n  var finish = funct"
	"ion (ok, why) {\n    card.remove();\n    uploading = false;\n    if (ok) {\n      toast(fill(\"{{js|{1} c"
	"aricato}}\", job.file.name), \"ok\");\n    } else if (!cancelled && why) {\n      toast(fill(\"{{js|Carica"
	"mento di {1} non riuscito ({2})}}\", job.file.name, why));\n    }\n    pump();\n  };\n\n  ensureDirs(job)\n"
	"    .then(function () {\n      if (cancelled || $(\"files-shell\").hidden) { finish(false); return; }\n "
	"     xhr = new XMLHttpRequest();\n      xhr.open(\"PUT\", endpoint(\"upload\", { path: jobDir(job) + job."
	"file.name }));\n      xhr.setRequestHeader(\"X-Sonix-Transfer\", \"1\");\n      xhr.upload.onprogress = fu"
	"nction (e) {\n        if (!e.lengthComputable || !e.total) { return; }\n        var pct = Math.min(99,"
	" Math.round(e.loaded / e.total * 100));\n        card.querySelector(\".bar > span\").style.width = pct "
	"+ \"%\";\n        card.querySelector(\".pct\").textContent = pct + \"%\";\n      };\n      xhr.onload = funct"
	"ion () {\n        if (xhr.status === 401) { showPair(); finish(false); }\n        else if (xhr.status "
	"=== 201) { finish(true); }\n        else { finish(false, statusMessage(xhr.status)); }\n      };\n     "
	" xhr.onerror = function () { connectionLost(); finish(false); };\n      xhr.onabort = function () { f"
	"inish(false); };\n      // Raw File bytes: the player streams to microSD without buffering the\n      "
	"// album or parsing a multipart form. XHR still provides upload progress.\n      xhr.send(job.file);\n"
	"    })\n    .catch(function (err) {\n      if (err instanceof TypeError) { connectionLost(); }\n      f"
	"inish(false, $(\"files-shell\").hidden \? null : err.message);\n    });\n}\n\n$(\"pick\").onclick = function "
	"() { $(\"files\").click(); };\n$(\"files\").onchange = function () { enqueue(this.files, false); this.val"
	"ue = \"\"; };\n\n$(\"pick-folder\").onclick = function () { $(\"folders\").click(); };\n$(\"folders\").onchange"
	" = function () { enqueue(this.files, true); this.value = \"\"; };\n\n/* Drag and drop over the whole pag"
	"e, which is how a desktop actually wants to\n   do this. */\n[\"dragenter\", \"dragover\"].forEach(functio"
	"n (name) {\n  document.addEventListener(name, function (e) {\n    e.preventDefault();\n    if (!$(\"file"
	"s-shell\").hidden) { document.body.classList.add(\"dragging\"); }\n  });\n});\n[\"dragleave\", \"drop\"].forEa"
	"ch(function (name) {\n  document.addEventListener(name, function (e) {\n    e.preventDefault();\n    if"
	" (name === \"dragleave\" && e.relatedTarget) { return; }\n    document.body.classList.remove(\"dragging\""
	");\n  });\n});\n/* A dropped folder does NOT arrive in dataTransfer.files -- that list holds\n   only fi"
	"les, and a dropped directory shows up there as an unreadable\n   zero-byte entry. The tree is reachab"
	"le only through the entry API, so walk\n   it, and fall back to the flat list when the browser has no"
	" entry API. */\nfunction walkEntry(entry, prefix, out) {\n  if (entry.isFile) {\n    return new Promise"
	"(function (resolve) {\n      entry.file(function (file) {\n        if (prefix) { file.sonixRelativePat"
	"h = prefix + file.name; }\n        out.push(file);\n        resolve();\n      }, resolve);\n    });\n  }\n"
	"\n  if (!entry.isDirectory) { return Promise.resolve(); }\n\n  var reader = entry.createReader();\n  var"
	" here = prefix + entry.name + \"/\";\n\n  // readEntries hands back at most a hundred at a time and sign"
	"als the end\n  // with an empty batch, so it has to be called until it does.\n  var readBatch = functi"
	"on () {\n    return new Promise(function (resolve) {\n      reader.readEntries(function (entries) {\n  "
	"      if (!entries.length) { resolve(); return; }\n        var chain = Promise.resolve();\n        ent"
	"ries.forEach(function (child) {\n          chain = chain.then(function () { return walkEntry(child, h"
	"ere, out); });\n        });\n        chain.then(readBatch).then(resolve);\n      }, resolve);\n    });\n "
	" };\n\n  return readBatch();\n}\n\ndocument.addEventListener(\"drop\", function (e) {\n  if ($(\"files-shell\""
	").hidden) { return; }\n  var target = path;\n  var items = e.dataTransfer && e.dataTransfer.items;\n  v"
	"ar canWalk = items && items.length && typeof items[0].webkitGetAsEntry === \"function\";\n\n  if (!canWa"
	"lk) {\n    if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length) {\n      enqueue"
	"(e.dataTransfer.files, false);\n    }\n    return;\n  }\n\n  var entries = [];\n  for (var i = 0; i < item"
	"s.length; i++) {\n    var entry = items[i].webkitGetAsEntry();\n    if (entry) { entries.push(entry); "
	"}\n  }\n  if (!entries.length) {\n    if (e.dataTransfer.files.length) { enqueue(e.dataTransfer.files, "
	"false, target); }\n    return;\n  }\n\n  var files = [];\n  var anyFolder = entries.some(function (entry)"
	" { return entry.isDirectory; });\n  var chain = Promise.resolve();\n\n  entries.forEach(function (entry"
	") {\n    chain = chain.then(function () { return walkEntry(entry, \"\", files); });\n  });\n\n  chain.then"
	"(function () {\n    if (files.length) { enqueue(files, anyFolder, target); }\n  });\n});\n\n/* --- go ---"
	"-------------------------------------------------------------- */\n\nupdateHiddenButton();\nvar scanned"
	"Code = window.location.hash.slice(1);\nif (scannedCode) {\n  // Don't leave the temporary pairing code"
	" in the address bar or history.\n  window.history.replaceState(null, \"\", window.location.pathname);\n "
	" showPair();\n  pair(scannedCode);\n} else {\n  load(CARD); // a same-session reload can use the browse"
	"r's HttpOnly cookie\n}\n</script>\n</body>\n</html>\n";

#endif /* WEBPAGE_H */
